import{_ as r,a0 as l,w as p,s as d,ao as n,I as a,x as i,a1 as s,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"如何在 Linux 上录制你的终端操作 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上录制你的终端操作 | LCTT (201607) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上录制你的终端操作 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上录制你的终端操作 | LCTT (201607) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201607/20160609 How to record your terminal session on Linux","title":"如何在 Linux 上录制你的终端操作","tag":"201607","desc":""},"relativePath":"201607/20160609 How to record your terminal session on Linux.md","filePath":"[post].md"}'),g={name:"201607/20160609 How to record your terminal session on Linux.md"};function h(c,t,u,f,m,k){const e=l("Link");return p(),d("div",null,[t[16]||(t[16]=n('<h1 id="如何在-linux-上录制你的终端操作" tabindex="-1">如何在 Linux 上录制你的终端操作 <a class="header-anchor" href="#如何在-linux-上录制你的终端操作" aria-label="Permalink to “如何在 Linux 上录制你的终端操作”">​</a></h1><p>录制一个终端操作可能是一个帮助他人学习 Linux 、展示一系列正确命令行操作的和分享知识的通俗易懂方法。不管是出于什么目的，从终端复制粘贴文本需要重复很多次，而录制视频的过程也是相当麻烦，有时候还不能录制。在这次的文章中，我们将简单的了解一下以 gif 格式记录和分享终端会话的方法。</p><h3 id="预先要求" tabindex="-1">预先要求 <a class="header-anchor" href="#预先要求" aria-label="Permalink to “预先要求”">​</a></h3><p>如果你只是希望能记录你的终端会话，并且能在终端进行回放或者和他人分享，那么你只需要一个叫做：ttyrec 的软件。Ubuntu 用户可以通过运行这行代码进行安装：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install ttyrec</span></span></code></pre></div><p>如果你想将生成的视频转换成一个 gif 文件，这样能够和那些不使用终端的人分享，就可以发布到网站上去，或者你只是想做一个 gif 方便使用而不想写命令。那么你需要安装额外的两个软件包。第一个就是 imagemagick , 你可以通过以下的命令安装：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install imagemagick</span></span></code></pre></div>',7)),a("p",null,[t[1]||(t[1]=i("第二个软件包就是：tty2gif.py，访问其",-1)),s(e,{href:"https://bitbucket.org/antocuni/tty2gif/raw/61d5596c916512ce5f60fcc34f02c686981e6ac6/tty2gif.py"},{default:o(()=>[...t[0]||(t[0]=[i("项目网站",-1)])]),_:1}),t[2]||(t[2]=i("下载。这个软件包需要安装如下依赖:",-1))]),t[17]||(t[17]=n(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install python-opster</span></span></code></pre></div><h3 id="录制" tabindex="-1">录制 <a class="header-anchor" href="#录制" aria-label="Permalink to “录制”">​</a></h3><p>开始录制终端操作，你需要的仅仅是键入 <code>ttyprec</code> ，然后回车。这个命令将会在后台运行一个实时的记录工具。我们可以通过键入<code>exit</code>或者<code>ctrl+d</code>来停止。ttyrec 默认会在主目录下创建一个<code>ttyrecord</code>的文件。</p><p><img src="https://www.howtoforge.com/images/how-to-record-your-terminal-session-on-linux/pic_1.jpg" alt=""></p><p><img src="https://www.howtoforge.com/images/how-to-record-your-terminal-session-on-linux/pic_2.jpg" alt=""></p><p><img src="https://www.howtoforge.com/images/how-to-record-your-terminal-session-on-linux/pic_3.jpg" alt=""></p><h3 id="回放" tabindex="-1">回放 <a class="header-anchor" href="#回放" aria-label="Permalink to “回放”">​</a></h3><p>回放这个文件非常简单。你只需要打开终端并且使用 <code>ttyplay</code> 命令打开 <code>ttyrecord</code> 文件即可。(在这个例子里，我们使用 ttyrecord 作为文件名，当然，你也可以改成你用的文件名)</p><p><img src="https://www.howtoforge.com/images/how-to-record-your-terminal-session-on-linux/pic_4.jpg" alt=""></p><p>然后就可以开始播放这个文件。这个视频记录了所有的操作，包括你的删除，修改。这看起来像一个拥有自我意识的终端，但是这个命令执行的过程并不是只是为了给系统看，而是为了更好的展现给人。</p><p>注意一点，播放这个记录是完全可控的，你可以通过点击 <code>+</code> 或者 <code>-</code> 进行加速减速，或者 <code>0</code>和 <code>1</code> 暂停和恢复播放。</p><h3 id="导出成-gif" tabindex="-1">导出成 GIF <a class="header-anchor" href="#导出成-gif" aria-label="Permalink to “导出成 GIF”">​</a></h3><p>为了方便，我们通常会将视频记录转换为 gif 格式，并且，这个非常容易做到。以下是方法：</p><p>将之前下载的 tty2gif.py 这个文件拷贝到 ttyprecord 文件（或者你命名的那个视频文件）相同的目录，然后在这个目录下打开终端，输入命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>python tty2gif.py typing ttyrecord</span></span></code></pre></div><p>如果出现了错误，检查一下你是否有安装 python-opster 包。如果还是有错误，使用如下命令进行排除。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install xdotool</span></span>
<span class="line"><span>export WINDOWID=$(xdotool getwindowfocus)</span></span></code></pre></div><p>然后重复这个命令 <code>python tty2gif.py</code> 并且你将会看到在 ttyrecord 目录下多了一些 gif 文件。</p><p><img src="https://www.howtoforge.com/images/how-to-record-your-terminal-session-on-linux/pic_5.jpg" alt=""></p><p>接下来的一步就是整合所有的 gif 文件，将他打包成一个 gif 文件。我们通过使用 imagemagick 工具。输入下列命令:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>convert -delay 25 -loop 0 *.gif example.gif</span></span></code></pre></div><p><img src="https://www.howtoforge.com/images/how-to-record-your-terminal-session-on-linux/pic_6.jpg" alt=""></p><p>你可以使用任意的文件名，我用的是 example.gif。 并且，你可以改变这个延时和循环时间。 Enjoy。</p><p><img src="https://www.howtoforge.com/images/how-to-record-your-terminal-session-on-linux/example.gif" alt=""></p><hr>`,25)),a("p",null,[t[4]||(t[4]=i("via: ",-1)),s(e,{href:"https://www.howtoforge.com/tutorial/how-to-record-your-terminal-session-on-linux/"},{default:o(()=>[...t[3]||(t[3]=[i("https://www.howtoforge.com/tutorial/how-to-record-your-terminal-session-on-linux/",-1)])]),_:1})]),a("p",null,[t[8]||(t[8]=i("作者：",-1)),s(e,{href:"https://twitter.com/howtoforgecom"},{default:o(()=>[...t[5]||(t[5]=[i("Bill Toulas",-1)])]),_:1}),t[9]||(t[9]=i(" 译者：",-1)),s(e,{href:"https://github.com/MikeCoder"},{default:o(()=>[...t[6]||(t[6]=[i("MikeCoder",-1)])]),_:1}),t[10]||(t[10]=i(" 校对：",-1)),s(e,{href:"https://github.com/wxy"},{default:o(()=>[...t[7]||(t[7]=[i("wxy",-1)])]),_:1})]),a("p",null,[t[13]||(t[13]=i("本文由 ",-1)),s(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[11]||(t[11]=[i("LCTT",-1)])]),_:1}),t[14]||(t[14]=i(" 原创编译，",-1)),s(e,{href:"https://linux.cn/"},{default:o(()=>[...t[12]||(t[12]=[i("Linux中国",-1)])]),_:1}),t[15]||(t[15]=i(" 荣誉推出",-1))])])}const x=r(g,[["render",h]]);export{w as __pageData,x as default};
